def _keynote_slide_table_name_check_codec(root: Path) -> list[str]:
    """Require the existing strict field-8 discovery/name codec seam."""

    violations: list[str] = []
    codec_path = root / KEYNOTE_SLIDE_TABLE_NAME_CODEC_SOURCE
    if not codec_path.is_file():
        return [
            "focused litchi-keynote slide-table name public API is missing strict neutral "
            f"codec source: {KEYNOTE_SLIDE_TABLE_NAME_CODEC_SOURCE}"
        ]

    codec_raw_source = codec_path.read_text(encoding="utf-8")
    codec_source = _mask_rust_cfg_test_items(codec_raw_source)
    codec_code = _mask_rust_non_code(codec_source)
    for api in KEYNOTE_SLIDE_TABLE_NAME_CODEC_REQUIRED_APIS:
        if re.search(
            rf"\b(?:pub\s+)?(?:fn|struct|enum|type)\s+{re.escape(api)}\b",
            codec_code,
        ) is None:
            violations.append(
                "focused litchi-keynote slide-table name hidden codec is missing strict API "
                f"{api}: {KEYNOTE_SLIDE_TABLE_NAME_CODEC_SOURCE}"
            )
    for label, markers in KEYNOTE_SLIDE_TABLE_NAME_CODEC_REQUIRED_MARKER_GROUPS.items():
        if not all(marker in codec_code for marker in markers):
            violations.append(
                "focused litchi-keynote slide-table name hidden codec is missing "
                f"{label} marker: {KEYNOTE_SLIDE_TABLE_NAME_CODEC_SOURCE}"
            )

    codec_lib_path = root / KEYNOTE_SLIDE_TABLE_NAME_CODEC_PUBLIC_SOURCE
    codec_lib_source = (
        _mask_rust_cfg_test_items(codec_lib_path.read_text(encoding="utf-8"))
        if codec_lib_path.is_file()
        else ""
    )
    if re.search(
        rf"#\s*\[\s*doc\s*\(\s*hidden\s*\)\s*\][\s\r\n]*"
        rf"pub\s+mod\s+{re.escape(KEYNOTE_SLIDE_TABLE_NAME_CODEC_MODULE)}\b",
        codec_lib_source,
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table name public API is missing hidden codec "
            f"module {KEYNOTE_SLIDE_TABLE_NAME_CODEC_MODULE}: "
            f"{KEYNOTE_SLIDE_TABLE_NAME_CODEC_PUBLIC_SOURCE}"
        )

    # The neutral codec already owns malformed-wire fuzzing.  The focused
    # Keynote owner additionally needs an integration lifecycle and a bounded
    # command corpus once its gate activates.
    if re.search(r"(?m)#\s*\[\s*cfg\s*\(\s*test\s*\)\s*\]", codec_raw_source) is None:
        violations.append(
            "focused litchi-keynote slide-table name hidden codec is missing cfg(test) coverage: "
            f"{KEYNOTE_SLIDE_TABLE_NAME_CODEC_SOURCE}"
        )
    elif re.search(r"(?m)#\s*\[\s*test\s*\]", codec_raw_source) is None:
        violations.append(
            "focused litchi-keynote slide-table name hidden codec is missing #[test] coverage: "
            f"{KEYNOTE_SLIDE_TABLE_NAME_CODEC_SOURCE}"
        )

    for test_path in KEYNOTE_SLIDE_TABLE_NAME_TEST_SOURCES:
        absolute = root / test_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-keynote slide-table name boundary is missing integration test: "
                f"{test_path}"
            )
            continue
        test_source = absolute.read_text(encoding="utf-8")
        test_code = _mask_rust_non_code(test_source)
        if re.search(r"(?m)#\s*\[\s*test\s*\]", test_code) is None:
            violations.append(
                "focused litchi-keynote slide-table name integration test is missing #[test] coverage: "
                f"{test_path}"
            )
        if not re.search(
            r"\b(?:slide_table_name|edit_slide_table_name|apply_slide_table_name)\b",
            test_code,
        ):
            violations.append(
                "focused litchi-keynote slide-table name integration test does not exercise the owner: "
                f"{test_path}"
            )
        if KEYNOTE_SLIDE_TABLE_NAME_NOOP_PREVIEW_ZERO.search(test_code) is None:
            violations.append(
                "focused litchi-keynote slide-table name integration test must prove "
                "exact no-op deleted_previews == 0: "
                f"{test_path}"
            )
        if KEYNOTE_SLIDE_TABLE_NAME_CHANGED_PREVIEW_REPORT.search(test_code) is None:
            violations.append(
                "focused litchi-keynote slide-table name integration test must report "
                "root preview deletions for a changed rename: "
                f"{test_path}"
            )

    for fuzz_path in KEYNOTE_SLIDE_TABLE_NAME_FUZZ_SOURCES:
        absolute = root / fuzz_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-keynote slide-table name boundary is missing fuzz target: "
                f"{fuzz_path}"
            )
        elif "fuzz_target!" not in absolute.read_text(encoding="utf-8"):
            violations.append(
                "focused litchi-keynote slide-table name fuzz target is missing fuzz_target! harness: "
                f"{fuzz_path}"
            )
    for corpus in KEYNOTE_SLIDE_TABLE_NAME_FUZZ_CORPORA:
        if not (root / corpus).is_dir():
            violations.append(
                "focused litchi-keynote slide-table name boundary is missing fuzz corpus: "
                f"{corpus}"
            )
    return violations


def audit_keynote_slide_table_name_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce the selector-first, archive-free Keynote table-name facade."""

    if not _keynote_slide_table_name_owner_present(root):
        return []

    owner_path = root / KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE
    semantic_path = root / KEYNOTE_SLIDE_TABLE_NAME_SEMANTIC_SOURCE
    selector_path = root / KEYNOTE_SLIDE_TABLE_NAME_SELECTOR_SOURCE
    package_path = root / KEYNOTE_SLIDE_TABLE_NAME_EXPORT_SOURCES[0]
    lib_path = root / KEYNOTE_SLIDE_TABLE_NAME_EXPORT_SOURCES[1]
    paths = (owner_path, semantic_path, selector_path, package_path, lib_path)
    sources = {
        path: _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        if path.is_file()
        else ""
        for path in paths
    }
    code = {path: _mask_rust_non_code(source) for path, source in sources.items()}
    violations: list[str] = []

    if re.search(
        r"(?m)^pub[ \t]+mod[ \t]+slide_table_name\b",
        code[package_path] + code[lib_path],
    ):
        violations.append(
            "focused litchi-keynote slide-table name owner module must remain private: "
            f"{KEYNOTE_SLIDE_TABLE_NAME_EXPORT_SOURCES[0]}"
        )
    if re.search(
        r"(?m)^(?:pub[ \t]*\([ \t]*crate[ \t]*\)[ \t]+)?"
        r"mod[ \t]+slide_table_name\s*;",
        code[package_path],
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table name owner module is missing: "
            f"{KEYNOTE_SLIDE_TABLE_NAME_EXPORT_SOURCES[0]}"
        )

    for name in sorted(KEYNOTE_SLIDE_TABLE_NAME_CANONICAL_TYPES):
        for path in (owner_path, package_path, lib_path):
            if name not in _rust_canonical_exports(
                sources[path], KEYNOTE_SLIDE_TABLE_NAME_CANONICAL_TYPES
            ):
                violations.append(
                    "focused litchi-keynote slide-table name public API is missing canonical "
                    f"type {name}: {path.relative_to(root)}"
                )

    semantic_exports = _rust_canonical_exports(
        sources[semantic_path] + sources[lib_path],
        KEYNOTE_SLIDE_TABLE_NAME_SEMANTIC_TYPES,
    )
    for name in sorted(KEYNOTE_SLIDE_TABLE_NAME_SEMANTIC_TYPES - semantic_exports):
        violations.append(
            "focused litchi-keynote slide-table name semantic API is missing "
            f"{name}: {KEYNOTE_SLIDE_TABLE_NAME_SEMANTIC_SOURCE}"
        )
    if re.search(
        r"(?m)^pub[ \t]+mod[ \t]+transaction\b",
        code[semantic_path],
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table name semantic API is missing "
            f"slide::table::name::transaction: {KEYNOTE_SLIDE_TABLE_NAME_SEMANTIC_SOURCE}"
        )
    transaction_exports = _rust_canonical_exports(
        sources[semantic_path], KEYNOTE_SLIDE_TABLE_NAME_TRANSACTION_TYPES
    )
    for name in sorted(
        KEYNOTE_SLIDE_TABLE_NAME_TRANSACTION_TYPES - transaction_exports
    ):
        violations.append(
            "focused litchi-keynote slide-table name transaction API is missing "
            f"{name}: {KEYNOTE_SLIDE_TABLE_NAME_SEMANTIC_SOURCE}"
        )

    selector_exports = _rust_canonical_exports(
        sources[selector_path] + sources[lib_path],
        KEYNOTE_SLIDE_TABLE_NAME_SELECTOR_TYPES,
    )
    for name in sorted(KEYNOTE_SLIDE_TABLE_NAME_SELECTOR_TYPES - selector_exports):
        violations.append(
            "focused litchi-keynote slide-table name public API is missing selector "
            f"{name}: {KEYNOTE_SLIDE_TABLE_NAME_EXPORT_SOURCES[1]}"
        )
    if re.search(
        r"impl[ \t\r\n]+(?:[A-Za-z_][A-Za-z0-9_]*[ \t\r\n]*)?"
        r"TableSelector\b[\s\S]*?\bpub[ \t]+(?:const[ \t]+)?fn[ \t]+"
        r"(?:index|position)\b",
        code[selector_path],
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table name selector must expose checked "
            f"TableSelector::index/position: {KEYNOTE_SLIDE_TABLE_NAME_SELECTOR_SOURCE}"
        )

    owner_methods = {
        name: declaration
        for name, declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], "Package"
        )
    }
    for name in sorted(KEYNOTE_SLIDE_TABLE_NAME_PACKAGE_METHODS):
        declaration = owner_methods.get(name)
        if declaration is None:
            violations.append(
                "focused litchi-keynote slide-table name Package method is missing "
                f"{name}: {KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE}"
            )
            continue
        if name != "apply_slide_table_name":
            for selector in ("SlideSelector", "TableSelector"):
                if not re.search(rf"\b{selector}\b", declaration):
                    violations.append(
                        "focused litchi-keynote slide-table name Package method "
                        f"{name} must accept selector-first {selector}: "
                        f"{KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE}"
                    )
        elif "SlideTableNamePatch" not in declaration:
            violations.append(
                "focused litchi-keynote slide-table name apply method must accept "
                f"SlideTableNamePatch: {KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE}"
            )

    edit_methods = {
        name
        for name, _declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], "SlideTableNameEdit"
        )
    }
    for name in sorted(KEYNOTE_SLIDE_TABLE_NAME_EDIT_METHODS - edit_methods):
        violations.append(
            "focused litchi-keynote slide-table name edit is missing "
            f"{name}: {KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE}"
        )

    facade_names = (
        KEYNOTE_SLIDE_TABLE_NAME_CANONICAL_TYPES
        | KEYNOTE_SLIDE_TABLE_NAME_SEMANTIC_TYPES
        | KEYNOTE_SLIDE_TABLE_NAME_SELECTOR_TYPES
        | KEYNOTE_SLIDE_TABLE_NAME_PACKAGE_METHODS
        | KEYNOTE_SLIDE_TABLE_NAME_FLAT_ALIASES
    )
    dedicated_sources = {owner_path, semantic_path}
    for path in paths:
        dedicated = path in dedicated_sources
        # ``Error`` is ubiquitous in unrelated package errors.  It remains a
        # required semantic export, but alone must not select every public
        # declaration in the package/lib facade leak scan.
        selection_names = facade_names if dedicated else facade_names - {"Error"}
        for declaration, line_number in _rust_public_declarations(sources[path]):
            identifiers = {
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            }
            if not dedicated and not identifiers.intersection(selection_names):
                continue
            if "pub use" in declaration and "*" in declaration:
                violations.append(
                    "focused litchi-keynote slide-table name public API retains a glob "
                    f"re-export: {path.relative_to(root)}:{line_number}"
                )
            for identifier in sorted(identifiers):
                if identifier == "litchi_iwa_common":
                    reason = None
                elif identifier in KEYNOTE_SLIDE_TABLE_NAME_PROTO_ORIGINS:
                    reason = "protobuf type"
                elif identifier in KEYNOTE_SLIDE_TABLE_NAME_PHYSICAL_TYPES:
                    reason = "archive/IWA type"
                elif (
                    identifier == "wire"
                    or identifier in KEYNOTE_SLIDE_TABLE_NAME_WIRE_TYPES
                ):
                    reason = "wire type"
                else:
                    reason = _iwork_public_leak(identifier)
                if reason is not None:
                    violations.append(
                        "focused litchi-keynote slide-table name public API exposes "
                        f"{reason} {identifier}: {path.relative_to(root)}:{line_number}"
                    )
                if identifier in KEYNOTE_SLIDE_TABLE_NAME_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-keynote slide-table name public API retains flat "
                        f"alias {identifier}: {path.relative_to(root)}:{line_number}"
                    )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                violations.append(
                    "focused litchi-keynote slide-table name public API exposes raw byte "
                    f"slice {byte_slice}: {path.relative_to(root)}:{line_number}"
                )
            for match in KEYNOTE_SLIDE_TABLE_NAME_PUBLIC_RAW_ID_PARAMETER.finditer(
                declaration
            ):
                violations.append(
                    "focused litchi-keynote slide-table name public API exposes raw "
                    f"parameter {match.group(0).strip()}: "
                    f"{path.relative_to(root)}:{line_number}"
                )

    violations.extend(_keynote_slide_table_name_check_codec(root))
    return sorted(set(violations))


def audit_keynote_slide_table_name_resource_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require bounded field-8 rewriting, authority, and exact locality."""

    if not _keynote_slide_table_name_owner_present(root):
        return []
    owner_path = root / KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE
    owner_source = _mask_rust_cfg_test_items(
        owner_path.read_text(encoding="utf-8")
    )
    owner = _mask_rust_non_code(owner_source)
    core_path = root / KEYNOTE_SLIDE_TABLE_CORE_SOURCE
    if core_path.is_file():
        core_source = _mask_rust_cfg_test_items(
            core_path.read_text(encoding="utf-8")
        )
        owner = f"{owner}\n{_mask_rust_non_code(core_source)}"
    violations: list[str] = []
    for label, markers in KEYNOTE_SLIDE_TABLE_NAME_PACKAGE_MARKER_GROUPS.items():
        if not all(marker in owner for marker in markers):
            violations.append(
                "focused litchi-keynote slide-table name owner is missing "
                f"{label} marker: {KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE}"
            )
    for label, pattern in (
        (
            "one-shot table-model name rewrite",
            re.compile(r"\brewrite_table_model_name(?:_with_report)?\s*\("),
        ),
        (
            "legacy Numbers name helper",
            re.compile(r"\brename_table_in_package\s*\("),
        ),
    ):
        match = pattern.search(owner)
        if match is not None:
            line_number = owner.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-keynote slide-table name owner must not perform "
                f"{label}: {KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE}:{line_number}"
            )
    if re.search(
        r"deleted_previews\s*:\s*(?:usize\s*=\s*)?0|deleted_previews\s*=\s*0",
        owner,
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table name owner must preserve previews "
            f"with deleted_previews = 0: {KEYNOTE_SLIDE_TABLE_NAME_OWNER_SOURCE}"
        )
    return sorted(set(violations))


def _keynote_slide_table_headers_owner_present(root: Path) -> bool:
    """Return whether the Wave100 slide-table-header owner is active.

    The owner gate intentionally stops at the package module declaration, as
    with the adjacent Wave99 owner.  Until that wiring exists, an entirely
    absent or staged owner leaves this migration baseline dormant.
    """

    owner_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE
    package_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_EXPORT_SOURCES[0]
    package_source = (
        _mask_rust_non_code(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    return owner_path.is_file() and re.search(
        r"(?m)^(?:pub[ \t]*\([ \t]*crate[ \t]*\)[ \t]+)?"
        r"mod[ \t]+slide_table_headers\s*;",
        package_source,
    ) is not None


def _keynote_slide_table_headers_public_declaration(
    declaration: str,
    *,
    dedicated_source: bool,
) -> bool:
    """Select facade declarations without inspecting unrelated crate APIs."""

    if dedicated_source:
        return True
    identifiers = {
        match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
    }
    if (
        "slide_table_headers" in identifiers
        or ("package" in identifiers and "*" in declaration)
        or ("headers" in identifiers and "*" in declaration)
    ):
        return True
    return bool(
        identifiers
        & (
            KEYNOTE_SLIDE_TABLE_HEADERS_CANONICAL_TYPES
            | KEYNOTE_SLIDE_TABLE_HEADERS_SELECTOR_TYPES
            | KEYNOTE_SLIDE_TABLE_HEADERS_PACKAGE_METHODS
            | KEYNOTE_SLIDE_TABLE_HEADERS_FLAT_ALIASES
        )
    )


def _keynote_slide_table_headers_check_public_leaks(
    root: Path,
    sources: dict[Path, str],
    paths: tuple[Path, ...],
) -> list[str]:
    """Return public physical/wire/raw-ID leaks from the focused facade."""

    violations: list[str] = []
    owner_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE
    semantic_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_SEMANTIC_SOURCE
    for path in paths:
        dedicated = path in {owner_path, semantic_path}
        for declaration, line_number in _rust_public_declarations(sources[path]):
            if not _keynote_slide_table_headers_public_declaration(
                declaration, dedicated_source=dedicated
            ):
                continue
            identifiers = {
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            }
            for identifier in sorted(identifiers):
                if identifier == "litchi_iwa_common":
                    reason = None
                elif identifier in KEYNOTE_SLIDE_TABLE_HEADERS_PROTO_ORIGINS:
                    reason = "protobuf type"
                elif identifier in KEYNOTE_SLIDE_TABLE_HEADERS_PHYSICAL_TYPES:
                    reason = "archive/IWA type"
                elif identifier == "wire" or identifier in KEYNOTE_SLIDE_TABLE_HEADERS_WIRE_TYPES:
                    reason = "wire type"
                else:
                    reason = _iwork_public_leak(identifier)
                if reason is not None:
                    violations.append(
                        "focused litchi-keynote slide-table headers public API exposes "
                        f"{reason} {identifier}: {path.relative_to(root)}:{line_number}"
                    )
                if identifier in KEYNOTE_SLIDE_TABLE_HEADERS_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-keynote slide-table headers public API retains flat alias "
                        f"{identifier}: {path.relative_to(root)}:{line_number}"
                    )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                violations.append(
                    "focused litchi-keynote slide-table headers public API exposes raw byte slice "
                    f"{byte_slice}: {path.relative_to(root)}:{line_number}"
                )
            for match in KEYNOTE_SLIDE_TABLE_HEADERS_PUBLIC_RAW_ID_PARAMETER.finditer(
                declaration
            ):
                violations.append(
                    "focused litchi-keynote slide-table headers public API exposes raw "
                    f"parameter {match.group(0).strip()}: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            if "pub use" in declaration and "*" in declaration:
                violations.append(
                    "focused litchi-keynote slide-table headers public API retains a glob re-export: "
                    f"{path.relative_to(root)}:{line_number}"
                )
    return violations


def _keynote_slide_table_headers_check_codec(
    root: Path,
) -> list[str]:
    """Require the shared strict, prepared seven-field codec seam."""

    violations: list[str] = []
    codec_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_SOURCE
    if not codec_path.is_file():
        return [
            "focused litchi-keynote slide-table headers public API is missing strict neutral "
            f"codec source: {KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_SOURCE}"
        ]
    codec_raw_source = codec_path.read_text(encoding="utf-8")
    codec_source = _mask_rust_cfg_test_items(codec_raw_source)
    codec_code = _mask_rust_non_code(codec_source)
    for api in KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_REQUIRED_APIS:
        if re.search(
            rf"\b(?:pub\s+)?(?:fn|struct|enum|type)\s+{re.escape(api)}\b",
            codec_code,
        ) is None:
            violations.append(
                "focused litchi-keynote slide-table headers hidden codec is missing strict API "
                f"{api}: {KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_SOURCE}"
            )
    for label, markers in KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_REQUIRED_MARKER_GROUPS.items():
        if not all(marker in codec_code for marker in markers):
            violations.append(
                "focused litchi-keynote slide-table headers hidden codec is missing "
                f"{label} marker: {KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_SOURCE}"
            )
    codec_lib_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_PUBLIC_SOURCE
    codec_lib_source = (
        _mask_rust_cfg_test_items(codec_lib_path.read_text(encoding="utf-8"))
        if codec_lib_path.is_file()
        else ""
    )
    for codec_module in KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_MODULES:
        if re.search(
            rf"#\s*\[\s*doc\s*\(\s*hidden\s*\)\s*\][\s\r\n]*"
            rf"pub\s+mod\s+{re.escape(codec_module)}\b",
            codec_lib_source,
        ) is None:
            violations.append(
                "focused litchi-keynote slide-table headers public API is missing hidden codec "
                f"module {codec_module}: {KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_PUBLIC_SOURCE}"
            )

    # A strict owner needs both a unit-test seam and a fuzz target/corpus.  The
    # codec's own cfg(test) module is the low-level seam, while the
    # package integration test proves the selector-first owner is exercised.
    # Both are required once the owner gate activates.
    if re.search(r"(?m)#\s*\[\s*cfg\s*\(\s*test\s*\)\s*\]", codec_raw_source) is None:
        violations.append(
            "focused litchi-keynote slide-table headers hidden codec is missing cfg(test) coverage: "
            f"{KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_SOURCE}"
        )
    elif re.search(r"(?m)#\s*\[\s*test\s*\]", codec_raw_source) is None:
        violations.append(
            "focused litchi-keynote slide-table headers hidden codec is missing #[test] coverage: "
            f"{KEYNOTE_SLIDE_TABLE_HEADERS_CODEC_SOURCE}"
        )
    for test_path in KEYNOTE_SLIDE_TABLE_HEADERS_TEST_SOURCES:
        absolute = root / test_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-keynote slide-table headers boundary is missing integration test: "
                f"{test_path}"
            )
            continue
        # Integration tests are normally compiled as test crates and do not
        # carry a surrounding cfg(test) item.  Keep the raw test attribute and
        # owner call visible so a cfg-only decoy cannot satisfy this seam.
        test_source = absolute.read_text(encoding="utf-8")
        test_code = _mask_rust_non_code(test_source)
        if re.search(r"(?m)#\s*\[\s*test\s*\]", test_code) is None:
            violations.append(
                "focused litchi-keynote slide-table headers integration test is missing #[test] coverage: "
                f"{test_path}"
            )
        if not re.search(
            r"\b(?:slide_table_header_settings|edit_slide_table_headers|"
            r"apply_slide_table_headers)\b",
            test_code,
        ):
            violations.append(
                "focused litchi-keynote slide-table headers integration test does not exercise the owner: "
                f"{test_path}"
            )
    for fuzz_path in KEYNOTE_SLIDE_TABLE_HEADERS_FUZZ_SOURCES:
        absolute = root / fuzz_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-keynote slide-table headers boundary is missing fuzz target: "
                f"{fuzz_path}"
            )
        elif "fuzz_target!" not in absolute.read_text(encoding="utf-8"):
            violations.append(
                "focused litchi-keynote slide-table headers fuzz target is missing fuzz_target! harness: "
                f"{fuzz_path}"
            )
    for corpus in KEYNOTE_SLIDE_TABLE_HEADERS_FUZZ_CORPORA:
        if not (root / corpus).is_dir():
            violations.append(
                "focused litchi-keynote slide-table headers boundary is missing fuzz corpus: "
                f"{corpus}"
            )
    return violations


def audit_keynote_slide_table_headers_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce the selector-first, archive-free seven-field header facade."""

    if not _keynote_slide_table_headers_owner_present(root):
        return []
    owner_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE
    semantic_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_SEMANTIC_SOURCE
    selector_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_SELECTOR_SOURCE
    package_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_EXPORT_SOURCES[0]
    lib_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_EXPORT_SOURCES[1]
    paths = (owner_path, semantic_path, selector_path, package_path, lib_path)
    sources = {
        path: _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        if path.is_file()
        else ""
        for path in paths
    }
    code = {path: _mask_rust_non_code(source) for path, source in sources.items()}
    violations: list[str] = []

    package_code = code[package_path]
    if re.search(
        r"(?m)^pub[ \t]+mod[ \t]+slide_table_headers\b",
        code[package_path] + code[lib_path],
    ):
        violations.append(
            "focused litchi-keynote slide-table headers owner module must remain private: "
            f"{KEYNOTE_SLIDE_TABLE_HEADERS_EXPORT_SOURCES[0]}"
        )
    if re.search(
        r"(?m)^(?:pub[ \t]*\([ \t]*crate[ \t]*\)[ \t]+)?"
        r"mod[ \t]+slide_table_headers\s*;",
        package_code,
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table headers owner module is missing: "
            f"{KEYNOTE_SLIDE_TABLE_HEADERS_EXPORT_SOURCES[0]}"
        )

    for name in sorted(KEYNOTE_SLIDE_TABLE_HEADERS_CANONICAL_TYPES):
        for path in (owner_path, package_path, lib_path):
            if name not in _rust_canonical_exports(
                sources[path], KEYNOTE_SLIDE_TABLE_HEADERS_CANONICAL_TYPES
            ):
                violations.append(
                    "focused litchi-keynote slide-table headers public API is missing canonical "
                    f"type {name}: {path.relative_to(root)}"
                )

    semantic_exports = _rust_canonical_exports(
        sources[semantic_path] + sources[lib_path],
        KEYNOTE_SLIDE_TABLE_HEADERS_SEMANTIC_TYPES,
    )
    for name in sorted(KEYNOTE_SLIDE_TABLE_HEADERS_SEMANTIC_TYPES - semantic_exports):
        violations.append(
            "focused litchi-keynote slide-table headers semantic API is missing "
            f"{name}: {KEYNOTE_SLIDE_TABLE_HEADERS_SEMANTIC_SOURCE}"
        )
    if re.search(r"(?m)^pub[ \t]+mod[ \t]+transaction\b", code[semantic_path]) is None:
        violations.append(
            "focused litchi-keynote slide-table headers semantic API is missing "
            f"slide::table::headers::transaction: {KEYNOTE_SLIDE_TABLE_HEADERS_SEMANTIC_SOURCE}"
        )
    transaction_exports = _rust_canonical_exports(
        sources[semantic_path], KEYNOTE_SLIDE_TABLE_HEADERS_TRANSACTION_TYPES
    )
    for name in sorted(KEYNOTE_SLIDE_TABLE_HEADERS_TRANSACTION_TYPES - transaction_exports):
        violations.append(
            "focused litchi-keynote slide-table headers transaction API is missing "
            f"{name}: {KEYNOTE_SLIDE_TABLE_HEADERS_SEMANTIC_SOURCE}"
        )

    selector_exports = _rust_canonical_exports(
        sources[selector_path] + sources[lib_path],
        KEYNOTE_SLIDE_TABLE_HEADERS_SELECTOR_TYPES,
    )
    for name in sorted(KEYNOTE_SLIDE_TABLE_HEADERS_SELECTOR_TYPES - selector_exports):
        violations.append(
            "focused litchi-keynote slide-table headers public API is missing selector "
            f"{name}: {KEYNOTE_SLIDE_TABLE_HEADERS_EXPORT_SOURCES[1]}"
        )
    if re.search(
        r"impl[ \t\r\n]+(?:[A-Za-z_][A-Za-z0-9_]*[ \t\r\n]*)?"
        r"TableSelector\b[\s\S]*?\bpub[ \t]+(?:const[ \t]+)?fn[ \t]+"
        r"(?:index|position)\b",
        code[selector_path],
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table headers selector must expose checked "
            f"TableSelector::index/position: {KEYNOTE_SLIDE_TABLE_HEADERS_SELECTOR_SOURCE}"
        )

    owner_methods = {
        name: declaration
        for name, declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], "Package"
        )
    }
    for name in sorted(KEYNOTE_SLIDE_TABLE_HEADERS_PACKAGE_METHODS):
        declaration = owner_methods.get(name)
        if declaration is None:
            violations.append(
                "focused litchi-keynote slide-table headers Package method is missing "
                f"{name}: {KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE}"
            )
            continue
        if name != "apply_slide_table_headers":
            for selector in ("SlideSelector", "TableSelector"):
                if not re.search(rf"\b{selector}\b", declaration):
                    violations.append(
                        "focused litchi-keynote slide-table headers Package method "
                        f"{name} must accept selector-first {selector}: "
                        f"{KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE}"
                    )
    apply_declaration = owner_methods.get("apply_slide_table_headers")
    if apply_declaration is not None and "SlideTableHeaderPatch" not in apply_declaration:
        violations.append(
            "focused litchi-keynote slide-table headers apply method must accept "
            f"SlideTableHeaderPatch: {KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE}"
        )

    edit_methods = {
        name
        for name, _declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], "SlideTableHeaderEdit"
        )
    }
    for name in sorted(KEYNOTE_SLIDE_TABLE_HEADERS_EDIT_METHODS - edit_methods):
        violations.append(
            "focused litchi-keynote slide-table headers edit is missing "
            f"{name}: {KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE}"
        )

    violations.extend(
        _keynote_slide_table_headers_check_public_leaks(root, sources, paths)
    )
    violations.extend(_keynote_slide_table_headers_check_codec(root))
    return sorted(set(violations))


def audit_keynote_slide_table_headers_resource_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require bounded one-model rewriting and exact preservation policy."""

    if not _keynote_slide_table_headers_owner_present(root):
        return []
    owner_path = root / KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE
    owner_source = _mask_rust_cfg_test_items(owner_path.read_text(encoding="utf-8"))
    owner = _mask_rust_non_code(owner_source)
    violations: list[str] = []
    for label, markers in KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_MARKER_GROUPS.items():
        if not all(marker in owner for marker in markers):
            violations.append(
                "focused litchi-keynote slide-table headers owner is missing "
                f"{label} marker: {KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE}"
            )
    for label, pattern in KEYNOTE_SLIDE_TABLE_HEADERS_FORBIDDEN_OWNER_PATTERNS:
        match = pattern.search(owner)
        if match is not None:
            line_number = owner.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-keynote slide-table headers owner must not perform "
                f"{label}: {KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE}:{line_number}"
            )
    if re.search(
        r"deleted_previews\s*:\s*(?:usize\s*=\s*)?0|deleted_previews\s*=\s*0",
        owner,
    ) is None:
        violations.append(
            "focused litchi-keynote slide-table headers owner must preserve previews "
            f"with deleted_previews = 0: {KEYNOTE_SLIDE_TABLE_HEADERS_OWNER_SOURCE}"
        )
    return sorted(set(violations))


def _keynote_slide_table_headers_example_is_keynote(
    path: Path,
    source: str,
    match_start: int,
) -> bool:
    """Identify a Keynote branch in a shared iWork example conservatively."""

    line_start = source.rfind("\n", 0, match_start) + 1
    line_end = source.find("\n", match_start)
    if line_end < 0:
        line_end = len(source)
    line = source[line_start:line_end].lower()
    # A package receiver is already on the selector-first owner.  It may have
    # a method with the same spelling as the retired editor read, so do not
    # classify that call as a legacy host use merely because the file is named
    # `list_keynote_tables.rs`.
    prefix = line[: match_start - line_start]
    if re.search(r"\b(?:package|keynote_package)\s*\.\s*$", prefix):
        return False
    if re.search(r"\b(?:litchi_keynote::)?package\s*::\s*$", prefix, re.I):
        return False
    if "keynote" in path.stem.lower():
        return True
    if "keynote" in line:
        return True
    # A receiver named `keynote` is the unambiguous mixed-example branch.
    if re.search(r"\bkeynote\s*\.\s*(?:slide_table_header_settings|set_slide_table_header_settings)", line):
        return True
    prefix = source[:match_start]
    function_matches = list(
        re.finditer(r"\bfn\s+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b", prefix)
    )
    return bool(function_matches and "keynote" in function_matches[-1].group(1).lower())


def _keynote_slide_table_headers_call_is_legacy(
    source: str,
    match_start: int,
) -> bool:
    """Distinguish a raw editor receiver from the new package facade."""

    line_start = source.rfind("\n", 0, match_start) + 1
    prefix = source[line_start:match_start]
    if re.search(r"\b(?:package|keynote_package)\s*\.\s*$", prefix):
        return False
    if re.search(r"\b(?:litchi_keynote::)?Package\s*::\s*$", prefix):
        return False
    return True


def audit_iwa_keynote_slide_table_headers_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire raw Keynote header calls in production and Keynote examples.

    Tests and fixture modules remain compatibility coverage.  Shared examples
    are inspected branch-by-branch so Numbers/Pages uses of the common header
    vocabulary do not activate a Keynote-only retirement finding.
    """

    if not _keynote_slide_table_headers_owner_present(root):
        return []
    violations: list[str] = []
    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    declaration = re.compile(
        r"(?<![A-Za-z0-9_#])(?:pub(?:\([^()]*\))?[ \t\r\n]+)?"
        r"(?:unsafe[ \t\r\n]+|async[ \t\r\n]+|const[ \t\r\n]+)*"
        r"fn[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b"
    )
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            # Included test modules are separate files without a local cfg
            # attribute.  They deliberately retain raw host calls as tests.
            if path.name == "tests.rs" or "tests" in path.parts:
                continue
            source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
            code = _mask_rust_non_code(source)
            for match in declaration.finditer(code):
                name = match.group(1)
                if name in RETIRED_IWA_KEYNOTE_SLIDE_TABLE_HEADER_METHODS:
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Keynote slide-table-header method "
                        f"{name}: {path.relative_to(root)}:{line_number}"
                    )
            for pattern in IWA_KEYNOTE_SLIDE_TABLE_HEADERS_IMPORTS:
                for match in pattern.finditer(code):
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Keynote slide-table-header import: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            for match in IWA_KEYNOTE_SLIDE_TABLE_HEADERS_CALL.finditer(code):
                if not _keynote_slide_table_headers_call_is_legacy(
                    code, match.start()
                ):
                    continue
                line_start = code.rfind("\n", 0, match.start()) + 1
                line_end = code.find("\n", match.end())
                if line_end < 0:
                    line_end = len(code)
                line = code[line_start:line_end]
                if re.search(
                    rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b",
                    line,
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Keynote slide-table-header call "
                    f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
                )

    example_root = root / IWA_KEYNOTE_SLIDE_TABLE_HEADERS_EXAMPLE_ROOT
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            source = _mask_rust_cfg_test_items(
                example_path.read_text(encoding="utf-8")
            )
            code = _mask_rust_non_code(source)
            for match in IWA_KEYNOTE_SLIDE_TABLE_HEADERS_CALL.finditer(code):
                if not _keynote_slide_table_headers_call_is_legacy(
                    code, match.start()
                ):
                    continue
                if not _keynote_slide_table_headers_example_is_keynote(
                    example_path, code, match.start()
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Keynote slide-table-header example call "
                    f"{match.group('method')}: {example_path.relative_to(root)}:{line_number}"
                )
    return sorted(set(violations))


def _iwa_keynote_config_call_is_legacy(source: str, match_start: int) -> bool:
    """Classify a same-spelled call as editor/legacy or focused Package use."""

    line_start = source.rfind("\n", 0, match_start) + 1
    prefix = source[line_start:match_start]
    if re.search(
        r"\b(?:package|keynote_package|focused_package|sort_package|"
        r"title_package|lock_package|name_package|table_name_package|"
        r"focused_keynote)\s*(?:\(\))?\s*\.\s*$",
        prefix,
    ):
        return False
    # Rust method chains are commonly formatted with the receiver on the
    # preceding line (`let patch = package\n    .edit_...`).  Keep the
    # receiver-aware distinction across that formatting boundary too.
    lookback = source[max(0, match_start - 240) : match_start]
    if re.search(
        r"\b(?:package|keynote_package|focused_package|sort_package|"
        r"title_package|lock_package|name_package|table_name_package|"
        r"focused_keynote)\s*\n[ \t]*\.\s*$",
        lookback,
    ):
        return False
    # Permit a visible fully qualified constructor chain such as
    # `litchi_keynote::Package::from_bytes(...).edit_...(...)` as well.
    if re.search(
        r"(?:litchi_keynote\s*::\s*)?Package\s*::[^;{}]*\.\s*$",
        prefix,
    ):
        return False
    return True


def _iwa_keynote_config_example_is_keynote(
    path: Path,
    source: str,
    match_start: int,
) -> bool:
    """Identify a Keynote branch in the shared IWA example directory."""

    if "keynote" in path.stem.lower():
        return True
    line_start = source.rfind("\n", 0, match_start) + 1
    line_end = source.find("\n", match_start)
    if line_end < 0:
        line_end = len(source)
    line = source[line_start:line_end].lower()
    if "keynote" in line:
        return True
    prefix = source[:match_start]
    function_matches = list(
        re.finditer(r"\bfn\s+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b", prefix)
    )
    return bool(function_matches and "keynote" in function_matches[-1].group(1).lower())


def _audit_iwa_keynote_slide_table_config_source_topology(
    root: Path,
    *,
    feature: str,
) -> list[str]:
    """Audit one retired IWA Keynote slide-table config route."""

    if feature == "title":
        owner_present = _keynote_slide_table_title_owner_present(root)
        retired_methods = RETIRED_IWA_KEYNOTE_SLIDE_TABLE_TITLE_METHODS
        call_pattern = IWA_KEYNOTE_SLIDE_TABLE_TITLE_CALL
        numbers_helper = IWA_KEYNOTE_SLIDE_TABLE_TITLE_NUMBERS_HELPER
        label = "title"
        physical_methods: frozenset[str] = frozenset()
    elif feature == "sort":
        owner_present = _keynote_slide_table_sort_owner_present(root)
        retired_methods = RETIRED_IWA_KEYNOTE_SLIDE_TABLE_SORT_METHODS
        call_pattern = IWA_KEYNOTE_SLIDE_TABLE_SORT_CALL
        numbers_helper = IWA_KEYNOTE_SLIDE_TABLE_SORT_NUMBERS_HELPER
        label = "sort"
        physical_methods = frozenset(
            {"apply_slide_table_sort_order", "apply_slide_table_sort_order_to_rows"}
        )
    elif feature == "dimension":
        owner_present = _keynote_slide_table_dimension_owner_present(root)
        retired_methods = RETIRED_IWA_KEYNOTE_SLIDE_TABLE_DIMENSION_METHODS
        call_pattern = IWA_KEYNOTE_SLIDE_TABLE_DIMENSION_CALL
        numbers_helper = IWA_KEYNOTE_SLIDE_TABLE_DIMENSION_NUMBERS_HELPER
        label = "dimension"
        # Geometry/resize helpers remain physical compatibility machinery. They
        # have distinct names and are intentionally not part of call_pattern;
        # keep the explicit allowlist here so this policy is obvious and testable.
        physical_methods = IWA_KEYNOTE_SLIDE_TABLE_DIMENSION_PHYSICAL_METHODS
    else:  # pragma: no cover - private helper is called with fixed features.
        raise ValueError(f"unknown Keynote table-config feature: {feature}")

    if not owner_present:
        return []

    violations: list[str] = []
    focused_call_seen = False
    scanned_source = False
    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    declaration = re.compile(
        r"(?<![A-Za-z0-9_#])(?:pub(?:\([^()]*\))?[ \t\r\n]+)?"
        r"(?:unsafe[ \t\r\n]+|async[ \t\r\n]+|const[ \t\r\n]+)*"
        r"fn[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b"
    )

    def inspect_source(path: Path, *, example: bool) -> None:
        nonlocal focused_call_seen, scanned_source
        raw_source = path.read_text(encoding="utf-8")
        production_source = _mask_rust_cfg_test_items(raw_source)
        code = _mask_rust_non_code(production_source)
        scanned_source = True
        relative = path.relative_to(root)
        for match in declaration.finditer(code):
            name = match.group(1)
            if name in retired_methods:
                line_number = code.count("\n", 0, match.start()) + 1
                scope = "example " if example else ""
                violations.append(
                    f"retired litchi-iwa Keynote slide-table-{label} {scope}method "
                    f"{name}: {relative}:{line_number}"
                )

        for match in numbers_helper.finditer(code):
            if example and not _iwa_keynote_config_example_is_keynote(
                path, code, match.start()
            ):
                continue
            line_number = code.count("\n", 0, match.start()) + 1
            scope = "example " if example else ""
            violations.append(
                f"retired litchi-iwa Numbers persisted table-{label} {scope}helper "
                f"{match.group(0)}: {relative}:{line_number}"
            )

        if not example:
            for pattern in IWA_KEYNOTE_SLIDE_TABLE_DIMENSION_IMPORTS:
                for match in pattern.finditer(code):
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Keynote slide-table-dimension import: "
                        f"{relative}:{line_number}"
                    )

        for match in call_pattern.finditer(code):
            if example and not _iwa_keynote_config_example_is_keynote(
                path, code, match.start()
            ):
                continue
            method = match.group("method")
            line_start = code.rfind("\n", 0, match.start()) + 1
            line_end = code.find("\n", match.end())
            if line_end < 0:
                line_end = len(code)
            line = code[line_start:line_end]
            if re.search(rf"\bfn[ \t\r\n]+{re.escape(method)}\b", line):
                continue
            focused = not _iwa_keynote_config_call_is_legacy(code, match.start())
            if focused:
                focused_call_seen = True
                continue
            # The sort method has one intentionally retained raw-ID route:
            # physical Sort Now and its row-range executor.  Its Numbers
            # helpers have distinct `apply_*` names and are not matched by
            # the persisted-helper regex above.
            if method in physical_methods:
                continue
            line_number = code.count("\n", 0, match.start("method")) + 1
            scope = "example " if example else ""
            violations.append(
                f"retired litchi-iwa Keynote slide-table-{label} {scope}call "
                f"{method}: {relative}:{line_number}"
            )

    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            if path.name == "tests.rs" or "tests" in path.parts:
                continue
            inspect_source(path, example=False)

    example_root = root / IWA_KEYNOTE_SLIDE_TABLE_CONFIG_EXAMPLE_ROOT
    if example_root.is_dir():
        for path in sorted(example_root.rglob("*.rs")):
            raw_source = path.read_text(encoding="utf-8")
            production_source = _mask_rust_cfg_test_items(raw_source)
            code = _mask_rust_non_code(production_source)
            relevant = "keynote" in path.stem.lower()
            if not relevant:
                relevant = any(
                    _iwa_keynote_config_example_is_keynote(path, code, match.start())
                    for match in (
                        *call_pattern.finditer(code),
                        *numbers_helper.finditer(code),
                    )
                )
            if not relevant:
                continue
            inspect_source(path, example=True)

    if scanned_source and not focused_call_seen:
        violations.append(
            f"litchi-iwa Keynote slide-table-{label} persisted configuration must "
            "call the focused litchi-keynote Package"
        )
    return sorted(set(violations))


def audit_iwa_keynote_slide_table_title_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire raw Keynote title configuration in favor of Package calls."""

    return _audit_iwa_keynote_slide_table_config_source_topology(root, feature="title")


def audit_iwa_keynote_slide_table_sort_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire persisted raw sort routes while preserving physical Sort Now."""

    return _audit_iwa_keynote_slide_table_config_source_topology(root, feature="sort")


def audit_iwa_keynote_slide_table_dimension_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire raw persisted dimensions while preserving physical geometry."""

    return _audit_iwa_keynote_slide_table_config_source_topology(
        root, feature="dimension"
    )


def audit_iwa_keynote_slide_table_name_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire raw Keynote table-name mutation in favor of Package calls.

    ``KeynoteEditor::rename_slide_table`` and the shared Numbers
    ``rename_table_in_package`` helper both accept native model identity.  A
    focused ``litchi_keynote::Package`` call remains valid, while editor/self
    calls, helper imports, and helper invocations disappear from production
    Keynote code and Keynote branches of shared examples.  Test modules,
    comments, and strings remain compatibility/fixture material.
    """

    if not _keynote_slide_table_name_owner_present(root):
        return []

    violations: list[str] = []
    focused_call_seen = False
    scanned_source = False
    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    declaration = re.compile(
        r"(?<![A-Za-z0-9_#])(?:pub(?:\([^()]*\))?[ \t\r\n]+)?"
        r"(?:unsafe[ \t\r\n]+|async[ \t\r\n]+|const[ \t\r\n]+)*"
        r"fn[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b"
    )

    def inspect_source(path: Path, *, example: bool) -> None:
        nonlocal focused_call_seen, scanned_source
        raw_source = path.read_text(encoding="utf-8")
        production_source = _mask_rust_cfg_test_items(raw_source)
        code = _mask_rust_non_code(production_source)
        scanned_source = True
        relative = path.relative_to(root)

        for match in declaration.finditer(code):
            name = match.group(1)
            if name not in RETIRED_IWA_KEYNOTE_SLIDE_TABLE_NAME_METHODS:
                continue
            line_number = code.count("\n", 0, match.start()) + 1
            scope = "example " if example else ""
            violations.append(
                "retired litchi-iwa Keynote slide-table-name "
                f"{scope}method {name}: {relative}:{line_number}"
            )

        for pattern in IWA_KEYNOTE_SLIDE_TABLE_NAME_IMPORTS:
            for match in pattern.finditer(code):
                if example and not _iwa_keynote_config_example_is_keynote(
                    path, code, match.start()
                ):
                    continue
                line_number = code.count("\n", 0, match.start()) + 1
                scope = "example " if example else ""
                violations.append(
                    "retired litchi-iwa Keynote slide-table-name "
                    f"{scope}helper import: {relative}:{line_number}"
                )

        for match in IWA_KEYNOTE_SLIDE_TABLE_NAME_NUMBERS_HELPER.finditer(code):
            if example and not _iwa_keynote_config_example_is_keynote(
                path, code, match.start()
            ):
                continue
            line_number = code.count("\n", 0, match.start("helper")) + 1
            scope = "example " if example else ""
            violations.append(
                "retired litchi-iwa Numbers persisted table-name "
                f"{scope}helper {match.group('helper')}: {relative}:{line_number}"
            )

        for match in IWA_KEYNOTE_SLIDE_TABLE_NAME_CALL.finditer(code):
            method = match.group("method")
            if example and method != "rename_slide_table":
                if not _iwa_keynote_config_example_is_keynote(
                    path, code, match.start()
                ):
                    continue
            line_start = code.rfind("\n", 0, match.start()) + 1
            line_end = code.find("\n", match.end())
            if line_end < 0:
                line_end = len(code)
            line = code[line_start:line_end]
            if re.search(rf"\bfn[ \t\r\n]+{re.escape(method)}\b", line):
                continue
            focused = not _iwa_keynote_config_call_is_legacy(code, match.start())
            if focused:
                focused_call_seen = True
                continue
            line_number = code.count("\n", 0, match.start("method")) + 1
            scope = "example " if example else ""
            violations.append(
                "retired litchi-iwa Keynote slide-table-name "
                f"{scope}call {method}: {relative}:{line_number}"
            )

    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            if path.name == "tests.rs" or "tests" in path.parts:
                continue
            inspect_source(path, example=False)

    example_root = root / IWA_KEYNOTE_SLIDE_TABLE_NAME_EXAMPLE_ROOT
    if example_root.is_dir():
        for path in sorted(example_root.rglob("*.rs")):
            raw_source = path.read_text(encoding="utf-8")
            production_source = _mask_rust_cfg_test_items(raw_source)
            code = _mask_rust_non_code(production_source)
            relevant = "keynote" in path.stem.lower()
            if not relevant:
                relevant = any(
                    method == "rename_slide_table"
                    or _iwa_keynote_config_example_is_keynote(
                        path, code, match.start()
                    )
                    for match in IWA_KEYNOTE_SLIDE_TABLE_NAME_CALL.finditer(code)
                    for method in (match.group("method"),)
                )
            if not relevant:
                relevant = any(
                    _iwa_keynote_config_example_is_keynote(path, code, match.start())
                    for match in IWA_KEYNOTE_SLIDE_TABLE_NAME_NUMBERS_HELPER.finditer(
                        code
                    )
                )
            if not relevant:
                continue
            inspect_source(path, example=True)

    # The legacy editor no longer exposes persisted table-name configuration.
    # Focused Package calls are allowed when a Keynote host/example needs that
    # operation, but their absence is also a valid complete retirement.
    return sorted(set(violations))


def audit_iwa_keynote_slide_table_lock_state_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire raw Keynote lock state while preserving physical sort executors.

    Persisted lock state belongs to the selector-first ``litchi-keynote``
    package.  The former editor module and its raw ``crate::table_lock``
    bridge must disappear from production.  This audit intentionally scans
    the whole Keynote host, including the physical sort executor, so a Sort
    Now implementation cannot acquire a hidden dependency on that retired
    helper.  The sort executor's ``apply_slide_table_sort_order*`` methods
    themselves remain allowed by the separate sort ratchet.
    """

    if not _keynote_slide_table_lock_state_owner_present(root):
        return []

    violations: list[str] = []
    focused_call_seen = False
    scanned_source = False
    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    declaration = re.compile(
        r"(?<![A-Za-z0-9_#])(?:pub(?:\([^()]*\))?[ \t\r\n]+)?"
        r"(?:unsafe[ \t\r\n]+|async[ \t\r\n]+|const[ \t\r\n]+)*"
        r"fn[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b"
    )
    raw_module = re.compile(
        r"(?<![A-Za-z0-9_])(?:crate\s*::\s*)?table_lock\s*::"
    )

    def inspect_source(path: Path, *, example: bool) -> None:
        nonlocal focused_call_seen, scanned_source
        raw_source = path.read_text(encoding="utf-8")
        production_source = _mask_rust_cfg_test_items(raw_source)
        code = _mask_rust_non_code(production_source)
        scanned_source = True
        relative = path.relative_to(root)

        if not example and path == root / IWA_KEYNOTE_SLIDE_TABLE_LOCK_STATE_SOURCE:
            violations.append(
                "retired litchi-iwa Keynote slide-table-lock source returned: "
                f"{relative}"
            )

        for match in declaration.finditer(code):
            name = match.group(1)
            if name not in RETIRED_IWA_KEYNOTE_SLIDE_TABLE_LOCK_STATE_METHODS:
                continue
            line_number = code.count("\n", 0, match.start()) + 1
            scope = "example " if example else ""
            violations.append(
                "retired litchi-iwa Keynote slide-table-lock "
                f"{scope}method {name}: {relative}:{line_number}"
            )

        for match in raw_module.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-table-lock raw helper/import "
                f"{match.group(0).strip()}: {relative}:{line_number}"
            )

        for match in IWA_KEYNOTE_SLIDE_TABLE_LOCK_STATE_RAW_HELPER.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-table-lock raw helper/import "
                f"{match.group(0).strip()}: {relative}:{line_number}"
            )

        for match in IWA_KEYNOTE_SLIDE_TABLE_LOCK_STATE_CALL.finditer(code):
            if example and not _iwa_keynote_config_example_is_keynote(
                path, code, match.start()
            ):
                continue
            method = match.group("method")
            line_start = code.rfind("\n", 0, match.start()) + 1
            line_end = code.find("\n", match.end())
            if line_end < 0:
                line_end = len(code)
            line = code[line_start:line_end]
            if re.search(rf"\bfn[ \t\r\n]+{re.escape(method)}\b", line):
                continue
            focused = not _iwa_keynote_config_call_is_legacy(code, match.start())
            if focused:
                focused_call_seen = True
                continue
            line_number = code.count("\n", 0, match.start("method")) + 1
            scope = "example " if example else ""
            violations.append(
                "retired litchi-iwa Keynote slide-table-lock "
                f"{scope}call {method}: {relative}:{line_number}"
            )

    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            if path.name == "tests.rs" or "tests" in path.parts:
                continue
            inspect_source(path, example=False)

    example_root = root / IWA_KEYNOTE_SLIDE_TABLE_LOCK_STATE_EXAMPLE_ROOT
    if example_root.is_dir():
        for path in sorted(example_root.rglob("*.rs")):
            raw_source = path.read_text(encoding="utf-8")
            production_source = _mask_rust_cfg_test_items(raw_source)
            code = _mask_rust_non_code(production_source)
            relevant = "keynote" in path.stem.lower()
            if not relevant:
                relevant = any(
                    _iwa_keynote_config_example_is_keynote(path, code, match.start())
                    for match in IWA_KEYNOTE_SLIDE_TABLE_LOCK_STATE_CALL.finditer(code)
                )
            if not relevant:
                continue
            inspect_source(path, example=True)

    if scanned_source and not focused_call_seen:
        violations.append(
            "litchi-iwa Keynote slide-table-lock persisted state must call the "
            "focused litchi-keynote Package"
        )
    return sorted(set(violations))


def audit_iwa_keynote_movie_geometry_source_topology(root: Path = ROOT) -> list[str]:
    """Require a typed bridge while retaining the legacy geometry fallback.

    MovieGeometry intentionally does not cover native angle/flip/flags and
    synthetic compatibility graphs.  The legacy KeynoteEditor declarations
    and their internal calls therefore remain allowed in the focused host and
    its geometry helper.  The Wave111 completion audit takes over when the
    expanded owner explicitly activates, at which point all raw declarations,
    fallbacks, and native mutators are retired atomically.
    """

    if not _keynote_movie_geometry_owner_present(root):
        return []
    owner_path = root / KEYNOTE_MOVIE_GEOMETRY_OWNER_SOURCE
    if owner_path.is_file():
        owner = _mask_rust_non_code(
            _mask_rust_cfg_test_items(owner_path.read_text(encoding="utf-8"))
        )
        # Retire the Wave87 compatibility exemption atomically when the
        # expanded owner opts in.  Keep this dispatch here, in addition to
        # main(), so direct callers cannot accidentally retain raw fallback.
        if KEYNOTE_MOVIE_GEOMETRY_COMPLETE_ACTIVATION.search(owner) is not None:
            return audit_keynote_movie_geometry_completion_source_topology(root)
    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    if not source_root.is_dir():
        return []
    violations: list[str] = []
    public_typed_declaration = re.compile(
        r"(?m)^\s*pub(?:\([^()]*\))?\s+fn\s+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b"
    )
    typed_methods: set[str] = set()
    for path in sorted(source_root.rglob("*.rs")):
        source = _mask_rust_non_code(
            _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        )
        typed_methods.update(
            match.group(1)
            for match in public_typed_declaration.finditer(source)
            if match.group(1) in IWA_KEYNOTE_MOVIE_GEOMETRY_TYPED_METHODS
        )
        # `editor/tests.rs` is included by a cfg(test) module in editor.rs;
        # its compatibility calls are test-only even though the standalone
        # file does not carry the attribute itself.
        if path.name == "tests.rs":
            continue
        if path in {
            root / relative
            for relative in IWA_KEYNOTE_MOVIE_GEOMETRY_COMPATIBILITY_SOURCES
        }:
            continue
        for match in IWA_KEYNOTE_MOVIE_GEOMETRY_IDENTIFIER_POSITION_FALLBACK.finditer(
            source
        ):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "litchi-iwa Keynote movie-geometry caller retains identifier-to-position fallback "
                f"{match.group(0)}: {path.relative_to(root)}:{line_number}"
            )
        for match in IWA_KEYNOTE_MOVIE_GEOMETRY_RAW_ID_CALL.finditer(source):
            line_number = source.count("\n", 0, match.start("method")) + 1
            violations.append(
                "litchi-iwa Keynote movie-geometry caller retains raw-ID call "
                f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
            )

    for name in sorted(IWA_KEYNOTE_MOVIE_GEOMETRY_TYPED_METHODS - typed_methods):
        violations.append(
            "litchi-iwa Keynote movie-geometry typed selector method is missing "
            f"{name}: {IWA_KEYNOTE_MOVIE_GEOMETRY_SOURCE}"
        )

    for example_path in IWA_KEYNOTE_MOVIE_GEOMETRY_EXAMPLES:
        path = root / example_path
        if not path.is_file():
            continue
        source = _mask_rust_non_code(
            _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        )
        for match in IWA_KEYNOTE_MOVIE_GEOMETRY_RAW_ID_CALL.finditer(source):
            line_number = source.count("\n", 0, match.start("method")) + 1
            violations.append(
                "litchi-iwa Keynote movie-geometry focused example uses raw-ID call "
                f"{match.group('method')}: {example_path}:{line_number}"
            )
    return sorted(set(violations))


def audit_pages_page_layout_facade_source_topology(root: Path = ROOT) -> list[str]:
    """Reject physical identifiers and implementation types from the layout facade."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir():
        return []
    dedicated_sources = {
        root / path
        for path in PAGES_PAGE_LAYOUT_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    export_sources = {
        root / path for path in PAGES_PAGE_LAYOUT_EXPORT_SOURCES if (root / path).is_file()
    }
    violations: list[str] = []
    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        source = path.read_text(encoding="utf-8")
        declarations = [
            (declaration, line_number, dedicated_source)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for declaration, line_number, complete_source_scope in declarations:
            if not _is_pages_page_layout_public_declaration(
                declaration, dedicated_source=complete_source_scope
            ):
                continue
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                reason = _iwork_public_leak(identifier)
                if reason is None:
                    continue
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                violations.append(
                    "focused litchi-pages page-layout public API exposes "
                    f"{reason} {identifier}: {path.relative_to(root)}:{identifier_line}"
                )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                byte_slice_line = line_number + declaration.count(
                    "\n", 0, match.start()
                )
                violations.append(
                    "focused litchi-pages page-layout public API exposes "
                    f"raw byte slice {byte_slice}: "
                    f"{path.relative_to(root)}:{byte_slice_line}"
                )

    return sorted(set(violations))


def audit_pages_table_lock_facade_source_topology(root: Path = ROOT) -> list[str]:
    """Enforce the nested, archive-free Pages table-lock owner API."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    dedicated_sources = {
        root / path
        for path in PAGES_TABLE_LOCK_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    export_sources = {
        root / path
        for path in PAGES_TABLE_LOCK_EXPORT_SOURCES
        if (root / path).is_file()
    }
    violations: list[str] = []

    semantic_path = root / PAGES_TABLE_LOCK_SEMANTIC_SOURCE
    semantic_source = (
        semantic_path.read_text(encoding="utf-8")
        if semantic_path.is_file()
        else ""
    )
    semantic_exports = _rust_canonical_exports(
        semantic_source, frozenset(PAGES_TABLE_LOCK_SEMANTIC_TYPES)
    )
    for name in PAGES_TABLE_LOCK_SEMANTIC_TYPES:
        if name in semantic_exports:
            continue
        violations.append(
            "focused litchi-pages table-lock public API is missing "
            f"canonical table::lock type {name}: {PAGES_TABLE_LOCK_SEMANTIC_SOURCE}"
        )

    package_path = root / PAGES_TABLE_LOCK_PACKAGE_EXPORT_SOURCE
    package_source = (
        _mask_rust_non_code(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    owner_path = root / PAGES_TABLE_LOCK_OWNER_SOURCE
    owner_present = owner_path.is_file() or (
        PAGES_PACKAGE_TABLE_LOCK_MODULE.search(package_source) is not None
    )
    if owner_present:
        owner_helper_root = root / PAGES_TABLE_LOCK_OWNER_HELPER_ROOT
        if owner_helper_root.is_dir():
            dedicated_sources.update(owner_helper_root.rglob("*.rs"))
        if owner_path.is_file():
            dedicated_sources.add(owner_path)
        export_sources.add(package_path)
        canonical_exports = _rust_canonical_exports(
            owner_path.read_text(encoding="utf-8") if owner_path.is_file() else "",
            frozenset(PAGES_TABLE_LOCK_CANONICAL_TYPES),
        )
    else:
        canonical_exports = frozenset()
    for name in PAGES_TABLE_LOCK_CANONICAL_TYPES:
        if not owner_present or name in canonical_exports:
            continue
        violations.append(
            "focused litchi-pages table-lock public API is missing "
            f"canonical package table-lock type {name}: {PAGES_TABLE_LOCK_OWNER_SOURCE}"
        )

    lib_path = root / PAGES_TABLE_LOCK_EXPORT_SOURCES[0]
    lib_source = (
        _mask_rust_non_code(lib_path.read_text(encoding="utf-8"))
        if lib_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_TABLE_MODULE.search(lib_source) is None:
        violations.append(
            "focused litchi-pages table-lock public API is missing canonical "
            f"root table module: {PAGES_TABLE_LOCK_EXPORT_SOURCES[0]}"
        )

    table_path = root / PAGES_TABLE_LOCK_EXPORT_SOURCES[2]
    table_source = (
        _mask_rust_non_code(table_path.read_text(encoding="utf-8"))
        if table_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_TABLE_LOCK_MODULE.search(table_source) is None:
        violations.append(
            "focused litchi-pages table-lock public API is missing "
            "canonical table::lock module: "
            f"{PAGES_TABLE_LOCK_EXPORT_SOURCES[2]}"
        )
    if table_path.is_file():
        for declaration, line_number in _rust_public_declarations(table_source):
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if (
                identifiers[:2] == ["pub", "use"]
                and "lock" in identifiers
                and "*" in declaration
            ):
                violations.append(
                    "focused litchi-pages table-lock public API retains root aliases "
                    "via table::lock glob: "
                    f"{PAGES_TABLE_LOCK_EXPORT_SOURCES[2]}:{line_number}"
                )

    if owner_present:
        if PAGES_PACKAGE_TABLE_LOCK_MODULE.search(package_source) is None:
            violations.append(
                "focused litchi-pages table-lock public API is missing "
                f"private package owner module: {PAGES_TABLE_LOCK_PACKAGE_EXPORT_SOURCE}"
            )
        for match in PUBLIC_PAGES_PACKAGE_TABLE_LOCK_MODULE.finditer(package_source):
            line_number = package_source.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-pages table-lock public API exposes duplicate "
                "package::table_lock module: "
                f"{PAGES_TABLE_LOCK_PACKAGE_EXPORT_SOURCE}:{line_number}"
            )
        if not owner_path.is_file():
            violations.append(
                "focused litchi-pages table-lock public API is missing private "
                f"package owner source: {PAGES_TABLE_LOCK_OWNER_SOURCE}"
            )
        owner_source = (
            owner_path.read_text(encoding="utf-8") if owner_path.is_file() else ""
        )
        owner_methods = {
            name
            for declaration, _line_number in _rust_public_declarations(owner_source)
            for name, _nested_line in _rust_function_declarations(declaration)
        }
        for method in PAGES_TABLE_LOCK_PACKAGE_METHODS:
            if method in owner_methods:
                continue
            violations.append(
                "focused litchi-pages table-lock public API is missing Package "
                f"method {method}: {PAGES_TABLE_LOCK_OWNER_SOURCE}"
            )
        for method in sorted(PAGES_TABLE_LOCK_FLAT_METHODS & owner_methods):
            violations.append(
                "focused litchi-pages table-lock public API retains flat Package "
                f"method {method}: {PAGES_TABLE_LOCK_OWNER_SOURCE}"
            )

    # Search the whole facade, not only today's three export files. A new
    # sibling module must not create an alias that can later be globbed into
    # the crate root without crossing this ratchet.
    for path in sorted(source_root.rglob("*.rs")):
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        for declaration, line_number in _rust_public_declarations(source):
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if identifiers[:3] == ["pub", "mod", "table_lock"]:
                violations.append(
                    "focused litchi-pages table-lock public API exposes duplicate "
                    f"table_lock module: {path.relative_to(root)}:{line_number}"
                )

            if identifiers[:2] == ["pub", "use"] and "*" in declaration:
                wildcard_owner = (
                    "package" in identifiers
                    or "table_lock" in identifiers
                    or (path == table_path and "lock" in identifiers)
                )
                if wildcard_owner:
                    violations.append(
                        "focused litchi-pages table-lock public API retains root "
                        f"aliases via owner glob: {path.relative_to(root)}:{line_number}"
                    )

            if "as" in identifiers and identifiers[:2] == ["pub", "use"]:
                alias_index = identifiers.index("as")
                target_identifiers = identifiers[2:alias_index]
                alias = (
                    identifiers[alias_index + 1]
                    if alias_index + 1 < len(identifiers)
                    else ""
                )
                table_lock_target = bool(
                    set(target_identifiers) & PAGES_TABLE_LOCK_ALIAS_TARGETS
                ) or ("lock" in target_identifiers and "State" in target_identifiers)
                target = target_identifiers[-1] if target_identifiers else ""
                if table_lock_target and alias and alias != target:
                    violations.append(
                        "focused litchi-pages table-lock public API retains alternate "
                        f"alias {alias} for {target}: "
                        f"{path.relative_to(root)}:{line_number}"
                    )

            if identifiers[:2] == ["pub", "type"] and len(identifiers) >= 4:
                alias = identifiers[2]
                target_identifiers = identifiers[3:]
                table_lock_target = bool(
                    set(target_identifiers) & PAGES_TABLE_LOCK_ALIAS_TARGETS
                ) or ("lock" in target_identifiers and "State" in target_identifiers)
                canonical_state_alias = (
                    alias == "BodyTableLockState" and "State" in target_identifiers
                )
                if table_lock_target and not canonical_state_alias:
                    target = target_identifiers[-1]
                    if alias != target:
                        violations.append(
                            "focused litchi-pages table-lock public API retains "
                            f"alternate alias {alias} for {target}: "
                            f"{path.relative_to(root)}:{line_number}"
                        )

    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        source = path.read_text(encoding="utf-8")
        declarations = [
            (declaration, line_number, True, dedicated_source)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for (
            declaration,
            line_number,
            public_declaration,
            complete_source_scope,
        ) in declarations:
            if not _is_pages_table_lock_public_declaration(
                declaration, dedicated_source=complete_source_scope
            ):
                continue
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if (
                path == semantic_path
                and tuple(identifiers)
                == ("pub", "use", "litchi_iwa_common", "table", "lock", "State")
            ):
                continue
            public_use_or_type = identifiers[:2] in (["pub", "type"], ["pub", "use"])
            if (
                public_declaration
                and public_use_or_type
                and "*" in declaration
                and path in export_sources
            ):
                violations.append(
                    "focused litchi-pages table-lock public API retains root aliases "
                    "via table::lock glob: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                if public_declaration and identifier in PAGES_TABLE_LOCK_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-pages table-lock public API "
                        f"retains flat alias {identifier}: "
                        f"{path.relative_to(root)}:{identifier_line}"
                    )
                reason = _pages_table_lock_public_leak(identifier)
                if reason is None:
                    continue
                violations.append(
                    "focused litchi-pages table-lock public API exposes "
                    f"{reason} {identifier}: {path.relative_to(root)}:{identifier_line}"
                )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                byte_slice_line = line_number + declaration.count(
                    "\n", 0, match.start()
                )
                violations.append(
                    "focused litchi-pages table-lock public API exposes raw "
                    f"byte slice {byte_slice}: "
                    f"{path.relative_to(root)}:{byte_slice_line}"
                )

    return sorted(set(violations))


def audit_pages_table_title_facade_source_topology(root: Path = ROOT) -> list[str]:
    """Enforce the selector-first, archive-free Pages table-title API."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    dedicated_sources = {
        root / path
        for path in PAGES_TABLE_TITLE_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    helper_root = root / PAGES_TABLE_TITLE_OWNER_HELPER_ROOT
    if helper_root.is_dir():
        dedicated_sources.update(helper_root.rglob("*.rs"))
    export_sources = {
        root / path
        for path in PAGES_TABLE_TITLE_EXPORT_SOURCES
        if (root / path).is_file()
    }
    violations: list[str] = []

    semantic_path = root / PAGES_TABLE_TITLE_SEMANTIC_SOURCE
    semantic_source = (
        semantic_path.read_text(encoding="utf-8") if semantic_path.is_file() else ""
    )
    semantic_exports = _rust_canonical_exports(
        semantic_source, frozenset(PAGES_TABLE_TITLE_SEMANTIC_TYPES)
    )
    for name in PAGES_TABLE_TITLE_SEMANTIC_TYPES:
        if name in semantic_exports:
            continue
        violations.append(
            "focused litchi-pages table-title public API is missing "
            f"semantic table::title type {name}: "
            f"{PAGES_TABLE_TITLE_SEMANTIC_SOURCE}"
        )

    selector_path = root / PAGES_TABLE_TITLE_SELECTOR_SOURCE
    selector_source = (
        _mask_rust_non_code(selector_path.read_text(encoding="utf-8"))
        if selector_path.is_file()
        else ""
    )
    if "BodyTableSelector" not in _rust_canonical_exports(
        selector_source, frozenset({"BodyTableSelector"})
    ):
        violations.append(
            "focused litchi-pages table-title public API is missing canonical "
            f"BodyTableSelector: {PAGES_TABLE_TITLE_SELECTOR_SOURCE}"
        )

    owner_path = root / PAGES_TABLE_TITLE_OWNER_SOURCE
    owner_present = owner_path.is_file() or any(
        PAGES_PACKAGE_TABLE_TITLE_MODULE.search(
            _mask_rust_non_code(
                path.read_text(encoding="utf-8")
            )
        )
        for path in (root / PAGES_TABLE_TITLE_EXPORT_SOURCES[1],)
        if path.is_file()
    )
    if owner_present:
        if owner_path.is_file():
            dedicated_sources.add(owner_path)
            export_sources.add(root / PAGES_TABLE_TITLE_EXPORT_SOURCES[1])
        canonical_exports = _rust_canonical_exports(
            owner_path.read_text(encoding="utf-8") if owner_path.is_file() else "",
            frozenset(PAGES_TABLE_TITLE_CANONICAL_TYPES),
        )
    else:
        canonical_exports = frozenset()
    for name in PAGES_TABLE_TITLE_CANONICAL_TYPES:
        if owner_present and name in canonical_exports:
            continue
        violations.append(
            "focused litchi-pages table-title public API is missing "
            f"canonical package type {name}: {PAGES_TABLE_TITLE_OWNER_SOURCE}"
        )
    if owner_present:
        owner_source = (
            owner_path.read_text(encoding="utf-8") if owner_path.is_file() else ""
        )
        owner_methods = {
            name
            for declaration, _line_number in _rust_public_declarations(owner_source)
            for name, _nested_line in _rust_function_declarations(declaration)
        }
        for method in PAGES_TABLE_TITLE_PACKAGE_METHODS:
            if method in owner_methods:
                continue
            violations.append(
                "focused litchi-pages table-title public API is missing Package "
                f"method {method}: {PAGES_TABLE_TITLE_OWNER_SOURCE}"
            )
        for method in sorted(PAGES_TABLE_TITLE_FLAT_METHODS & owner_methods):
            violations.append(
                "focused litchi-pages table-title public API retains flat Package "
                f"method {method}: {PAGES_TABLE_TITLE_OWNER_SOURCE}"
            )

    lib_path = root / PAGES_TABLE_TITLE_EXPORT_SOURCES[0]
    lib_source = (
        _mask_rust_non_code(lib_path.read_text(encoding="utf-8"))
        if lib_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_TABLE_MODULE.search(lib_source) is None:
        violations.append(
            "focused litchi-pages table-title public API is missing canonical "
            f"root table module: {PAGES_TABLE_TITLE_EXPORT_SOURCES[0]}"
        )
    if "BodyTableSelector" not in _rust_canonical_exports(
        lib_source, frozenset({"BodyTableSelector"})
    ):
        violations.append(
            "focused litchi-pages table-title public API is missing root "
            f"BodyTableSelector re-export: {PAGES_TABLE_TITLE_EXPORT_SOURCES[0]}"
        )

    table_path = root / PAGES_TABLE_TITLE_EXPORT_SOURCES[2]
    table_source = (
        _mask_rust_non_code(table_path.read_text(encoding="utf-8"))
        if table_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_TABLE_TITLE_MODULE.search(table_source) is None:
        violations.append(
            "focused litchi-pages table-title public API is missing canonical "
            "table::title module: "
            f"{PAGES_TABLE_TITLE_EXPORT_SOURCES[2]}"
        )

    package_path = root / PAGES_TABLE_TITLE_EXPORT_SOURCES[1]
    package_source = (
        _mask_rust_non_code(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    if owner_present and PAGES_PACKAGE_TABLE_TITLE_MODULE.search(package_source) is None:
        violations.append(
            "focused litchi-pages table-title public API is missing private "
            f"package owner module: {PAGES_TABLE_TITLE_EXPORT_SOURCES[1]}"
        )
    if owner_present:
        for match in PUBLIC_PAGES_PACKAGE_TABLE_TITLE_MODULE.finditer(package_source):
            line_number = package_source.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-pages table-title public API exposes duplicate "
                "package::body_table_title module: "
                f"{PAGES_TABLE_TITLE_EXPORT_SOURCES[1]}:{line_number}"
            )

    # The complete facade tree is scanned so a newly added sibling module
    # cannot introduce a second export path or an alias hidden from the
    # established root/package/table files. cfg(test) items are deliberately
    # masked one item at a time; production declarations after test helpers
    # remain in the audit slice.
    for path in sorted(source_root.rglob("*.rs")):
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        for declaration, line_number in _rust_public_declarations(source):
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if identifiers[:3] == ["pub", "mod", "body_table_title"]:
                violations.append(
                    "focused litchi-pages table-title public API exposes duplicate "
                    f"body_table_title module: {path.relative_to(root)}:{line_number}"
                )
            if identifiers[:2] == ["pub", "use"] and "*" in declaration:
                owner_glob = (
                    "body_table_title" in identifiers
                    or "title" in identifiers
                    or "package" in identifiers
                )
                if owner_glob:
                    glob_label = (
                        "table::title glob" if path == table_path else "owner glob"
                    )
                    violations.append(
                        "focused litchi-pages table-title public API retains root "
                        f"aliases via {glob_label}: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "use"] and "as" in identifiers:
                alias_index = identifiers.index("as")
                target_identifiers = identifiers[2:alias_index]
                alias = (
                    identifiers[alias_index + 1]
                    if alias_index + 1 < len(identifiers)
                    else ""
                )
                target = target_identifiers[-1] if target_identifiers else ""
                if (
                    target in PAGES_TABLE_TITLE_ALIAS_TARGETS
                    or "body_table_title" in target_identifiers
                ) and alias and alias != target:
                    # A sibling table-settings semantic alias is not a title
                    # route; keep the title ratchet scoped to its own facade.
                    if alias == "BodyTableHeaderSettings":
                        continue
                    if path == semantic_path and alias in {
                        "Commit",
                        "Diagnostics",
                        "Edit",
                        "Error",
                        "LimitKind",
                        "Patch",
                    }:
                        continue
                    violations.append(
                        "focused litchi-pages table-title public API retains "
                        f"alternate alias {alias} for {target}: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "type"] and len(identifiers) >= 4:
                alias = identifiers[2]
                target_identifiers = identifiers[3:]
                target = target_identifiers[-1] if target_identifiers else ""
                if (
                    target in PAGES_TABLE_TITLE_ALIAS_TARGETS
                    or "body_table_title" in target_identifiers
                ) and alias != target:
                    if alias == "BodyTableHeaderSettings":
                        continue
                    violations.append(
                        "focused litchi-pages table-title public API retains "
                        f"alternate alias {alias} for {target}: "
                        f"{path.relative_to(root)}:{line_number}"
                    )

    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        source = path.read_text(encoding="utf-8")
        declarations = [
            (declaration, line_number, True, dedicated_source)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for (
            declaration,
            line_number,
            public_declaration,
            complete_source_scope,
        ) in declarations:
            if not _is_pages_table_title_public_declaration(
                declaration, dedicated_source=complete_source_scope
            ):
                continue
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if (
                public_declaration
                and path in export_sources
                and identifiers[:2] == ["pub", "use"]
                and "*" in declaration
            ):
                violations.append(
                    "focused litchi-pages table-title public API retains root "
                    f"aliases via table::title glob: {path.relative_to(root)}:{line_number}"
                )
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                if public_declaration and identifier in PAGES_TABLE_TITLE_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-pages table-title public API retains flat "
                        f"alias {identifier}: {path.relative_to(root)}:{identifier_line}"
                    )
                reason = _pages_table_title_public_leak(identifier)
                if reason is None:
                    continue
                violations.append(
                    "focused litchi-pages table-title public API exposes "
                    f"{reason} {identifier}: {path.relative_to(root)}:{identifier_line}"
                )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                byte_slice_line = line_number + declaration.count(
                    "\n", 0, match.start()
                )
                violations.append(
                    "focused litchi-pages table-title public API exposes raw byte "
                    f"slice {byte_slice}: {path.relative_to(root)}:{byte_slice_line}"
                )

    return sorted(set(violations))


def audit_pages_table_headers_facade_source_topology(root: Path = ROOT) -> list[str]:
    """Enforce the selector-first, archive-free Pages table-header API."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    dedicated_sources = {
        root / path
        for path in PAGES_TABLE_HEADERS_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
